bool ctCopyPresetBytes(File& source, File& destination, size_t count) {
  uint8_t buffer[256];
  while (count) {
    const size_t part = std::min(count, sizeof(buffer));
    if (source.readBytes(reinterpret_cast<char*>(buffer), part) != part || destination.write(buffer, part) != part) return false;
    count -= part;
    yield();
  }
  return true;
}

